// Completed resource stages drive the emblem; no timer invents loading progress.
const root=document.documentElement,screen=document.querySelector('#loading-screen'),bg=document.querySelector('relief-background'),fill=document.querySelector('#loading-fill'),stage=document.querySelector('#loading-stage');
const protectedNodes=[...document.querySelectorAll('header,main,.rail,.skip')];protectedNodes.forEach(e=>{e.inert=true;e.dataset.loadingInert=''});
let fonts=false,done=false,value=0,frame=0;
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
function sector(p){const cx=50,cy=50,r=75,a=p*Math.PI*2,x=cx+Math.sin(a)*r,y=cy-Math.cos(a)*r;return p>=1?'M0 0H100V100H0Z':`M${cx} ${cy}L${cx} ${cy-r}A${r} ${r} 0 ${p>.5?1:0} 1 ${x} ${y}Z`}
function progress(target){cancelAnimationFrame(frame);if(reduce.matches){value=target;fill.setAttribute('d',sector(value));return}const tick=()=>{value+=(target-value)*.18;if(Math.abs(target-value)<.002)value=target;fill.setAttribute('d',sector(value));if(value!==target)frame=requestAnimationFrame(tick)};tick();screen.dataset.progress=String(target)}
function finish(failed=false){if(done)return;done=true;observer.disconnect();clearTimeout(timeout);clearTimeout(window.loadingEscape);cancelAnimationFrame(frame);fill.setAttribute('d',sector(1));screen.dataset.progress='1';stage.textContent=failed?'已进入简化页面':'准备就绪';if(failed)document.querySelector('#loading-notice').hidden=false;
requestAnimationFrame(()=>requestAnimationFrame(()=>{screen.classList.add('leaving');root.classList.remove('loading');protectedNodes.forEach(e=>{e.inert=false;delete e.dataset.loadingInert});bg.flowField?.reset();bg.textFlowField?.reset();bg.startedAt=performance.now()-1200;bg.animate?.();setTimeout(()=>{screen.hidden=true;screen.classList.remove('leaving')},reduce.matches?0:700)}));}
function check(){if(done)return;if(['fallback','error'].includes(bg.dataset.renderer)||bg.dataset.depth==='error'||bg.dataset.model==='fallback'){finish(true);return}const image=bg.dataset.renderer==='webgl',depth=bg.dataset.depth==='ready',model=bg.dataset.model==='ready';progress((image?.2:0)+(depth?.25:0)+(model?.4:0)+(fonts?.1:0));stage.textContent=!image?'准备石膏质感':!depth?'准备光影':!model?'唤醒浮雕':'即将呈现';if(image&&depth&&model&&fonts){bg.draw();if(bg.gl?.getError()===0)finish();else finish(true)}}
const observer=new MutationObserver(check);observer.observe(bg,{attributes:true,attributeFilter:['data-renderer','data-depth','data-model']});bg.addEventListener('relief-error',()=>finish(true),{once:true});const timeout=setTimeout(()=>finish(true),18000);document.fonts.ready.then(()=>{fonts=true;check()});check();
